describe('Total Price Update on Quantity Change', () => {
  beforeEach(() => {
    cy.visit('/cart');
  });

  it('should update total price when quantity is increased', () => {
    // Verify initial state
    cy.get('[data-testid="product-item"]').first().should('be.visible');
    cy.get('[data-testid="product-name"]').should('contain', 'Sample Product');
    cy.get('[data-testid="product-price"]').should('contain', '$10.00');
    cy.get('[data-testid="quantity-input"]').should('be.visible');
    cy.get('[data-testid="quantity-input"]').type('2');
    cy.get('[data-testid="update-button"]').click();

    // Verify total price is updated
    cy.get('[data-testid="total-price"]').should('contain', '$20.00');
    cy.get('[data-testid="total-price"]').should('be.visible');

    // Verify quantity is updated
    cy.get('[data-testid="quantity-input"]').should('have.value', '2');
  });

  it('should update total price when quantity is decreased', () => {
    // Verify initial state
    cy.get('[data-testid="product-item"]').first().should('be.visible');
    cy.get('[data-testid="product-name"]').should('contain', 'Sample Product');
    cy.get('[data-testid="product-price"]').should('contain', '$10.00');
    cy.get('[data-testid="quantity-input"]').should('be.visible');
    cy.get('[data-testid="quantity-input"]').type('3');
    cy.get('[data-testid="update-button"]').click();

    // Verify total price is updated
    cy.get('[data-testid="total-price"]').should('contain', '$30.00');

    // Verify quantity is decreased
    cy.get('[data-testid="quantity-input"]').should('have.value', '3');

    // Verify total price is still visible
    cy.get('[data-testid="total-price"]').should('be.visible');
  });

  it('should handle edge case when quantity is set to zero', () => {
    // Verify initial state
    cy.get('[data-testid="product-item"]').first().should('be.visible');
    cy.get('[data-testid="product-name"]').should('contain', 'Sample Product');
    cy.get('[data-testid="product-price"]').should('contain', '$10.00');
    cy.get('[data-testid="quantity-input"]').should('be.visible');

    // Verify total price is initially correct
    cy.get('[data-testid="total-price"]').should('contain', '$10.00');

    // Set quantity to zero
    cy.get('[data-testid="quantity-input"]').type('0');
    cy.get('[data-testid="update-button"]').click();

    // Verify total price is updated to zero
    cy.get('[data-testid="total-price"]').should('contain', '$0.00');

    // Verify quantity input is still visible
    cy.get('[data-testid="quantity-input"]').should('be.visible');
  });
});
